#include "cpu.hpp"
#include <iostream>
#include <stdexcept>
using namespace pc;
static unsigned checks;
static void check(bool ok) { ++checks; if (!ok) throw std::runtime_error("derived TLB invariant"); }
int main() {
    CPU c(2*1024*1024);
    c.cr[0]=0x80000011; c.cr[3]=c.tlbCR3=0;
    constexpr uint32_t linear=0x9000;
    auto &ref=c.tlb[9]; auto &fast=c.nativeTLB[9];
    for (unsigned permissions=0;permissions<256;++permissions)
    for (bool dirty : {false,true}) {
        ref={9,c.tlbEpoch,0x100000,0x100,uint8_t(permissions),dirty};
        c.fillNativeTLB(linear);
        const auto key=uint64_t(c.tlbEpoch)<<32|9;
        check((fast.readTag & ~(1ull<<31))==key);
        check((fast.readTag==key)==bool(permissions&4));
        check((fast.writeTag==key)==bool(dirty && permissions==6));
        check(fast.addend+linear==reinterpret_cast<uintptr_t>(c.mem.data()+0x100000));
    }
    for (uint32_t frame : {0xa0000u,0xaf000u,0x200000u,0xfffff000u}) {
        ref={9,c.tlbEpoch,frame,0x100,6,true};c.fillNativeTLB(linear);
        check(!fast.readTag && !fast.writeTag);
    }
    ref={9,c.tlbEpoch,0x100000,0x100,6,true};c.fillNativeTLB(linear);
    c.a20=false;c.syncNativeTLB();check(!fast.readTag && !fast.writeTag);
    c.fillNativeTLB(linear);check(fast.addend+linear==reinterpret_cast<uintptr_t>(c.mem.data()));
    c.a20=true;c.fillNativeTLB(linear);
    auto replacement=c.mem;c.mem.swap(replacement);c.syncNativeTLB();
    check(!fast.readTag && !fast.writeTag);c.fillNativeTLB(linear);
    check(fast.addend+linear==reinterpret_cast<uintptr_t>(c.mem.data()+0x100000));
    ++c.executionEpoch;c.syncNativeTLB();check(!fast.readTag && !fast.writeTag);
    c.fillNativeTLB(linear);auto old=fast.readTag;c.flushTLB();
    check(old!=(uint64_t(c.tlbEpoch)<<32|9));c.fillNativeTLB(linear);
    check(!fast.readTag && !fast.writeTag);
    c.tlbEpoch=0xffffffffu;fast.readTag=fast.writeTag=uint64_t(1)<<32|9;c.flushTLB();
    check(c.tlbEpoch==1 && !fast.readTag && !fast.writeTag);
    c.mem.resize(0x100001);ref={9,c.tlbEpoch,0x100000,0x100,6,true};c.fillNativeTLB(linear);
    check(!fast.readTag && !fast.writeTag);
    std::cout << "Passed " << checks << " derived TLB checks\n";
}
